///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkResult = async function () {
    /* sdd-asis-lifecycle:begin checkResult — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tp = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType")))));
    if (tp === '1') {
        await alertE('비밀번호 변경이 완료되었습니다.\n다시 로그인하시기 바랍니다.', function() {
                $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil45000/jldfil45000.xml');
        });
    } else {
        if (tp === '2') {
            await alertE((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage"))))));
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_Save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.passwordForm || { elements: [] });
    if ($c.util.getComponent('ipt_bPwYn').getValue() !== "Y") {
        await alertE("현재 비밀번호를 확인하시기 바랍니다.");
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_bPw'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_pw'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_pwChk'))) {
        return;
    }
    if ($c.util.getComponent('ipt_pw').getValue()!== $c.util.getComponent('ipt_pwChk').getValue()) {
        await alertE('입력한 새 비밀번호가 일치하지 않습니다. 새 비밀번호를 확인하십시오.');
        return;
    }
    if (!await scwin.checkPassword($c.util.getComponent('ipt_pw').getValue())) {
        pw.focus();
        return;
    }
    if ($c.util.getComponent('ipt_isPass').getValue() !== "Y") {
        await alertE("입력하신 비밀번호 보안등급이 낮습니다. \n다시 입력하여 주시기 바랍니다.");
        return;
    }
    if ($c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'Y') {
        $c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'N';
    }
    confirmF("비밀번호를 변경하시겠습니까?", async function() {
            frm.action = '/main/pwChg.do?method=updatePassword';
            await scwin.tx_fn_Save();
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkPassword
 * @author Inswave
 * @date 2026. 09. 29
 * @param _password
 * @returns
 * @hidden N
*/
scwin.checkPassword = async function (_password) {
    /* sdd-asis-lifecycle:begin fn_CheckPassword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const pwVal = _password;
    if (pwVal.length < 9) {
        await alertE("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        return false;
    }
    const strChk = /^[\a-z0-9_!@#^&*()]{8,}$/;
    if (!(strChk.test(pwVal.toLowerCase()))) {
        await alertE("변경 비밀번호는 한글,띄어쓰기는 사용하실 수 없습니다.\n_!@#^&*() 이외의 특수문자는 사용하실 수 없습니다.");
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const sChar_t = "_!@#^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let numberCheck_t = false;
    for (var i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) != -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) != -1) {
            alphaCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) != -1) {
            numberCheck_t = true;
        }
    }
    if (sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) {
        await alertE("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        return false;
    }
    let sameCount = 1;
    let isCont = true;
    for (var i = 0; i < pwVal.length - 1; i++) {
        const currentChar = pwVal.charAt(i);
        const nextChar = pwVal.charAt(i + 1);
        const currentCharNum = parseInt(currentChar.charCodeAt(0));
        const continueCharNum = parseInt(nextChar.charCodeAt(0));
        if (currentChar === nextChar) {
            sameCount = sameCount + 1;
            if (sameCount >= 3) {
                break;
            }
        } else {
            sameCount = 1;
        }
        if (!(isCont && currentCharNum === continueCharNum - 1)) {
            isCont = false;
        }
    }
    if (sameCount >= 3) {
        await alertE('동일한 문자 또는 숫자가 3자 이상로 구성된 비밀번호는 사용할 수 없습니다.');
        return false;
    }
    if (isCont) {
        await alertE('주기성 문자(abcd, 1234 등)로 구성된 비밀번호는 사용할 수 없습니다.');
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await alertE('변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.');
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (var i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length == 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await alertE('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용할 수 없습니다.');
                    return false;
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDelayKeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param newPw
 * @returns
 * @hidden N
*/
scwin.fnDelayKeyup = async function (newPw) {
    /* sdd-asis-lifecycle:begin fnDelayKeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (newPw.length > 0) {
        if (await scwin.checkPassword(newPw)) {
            await scwin.checkIsBeforePW("B", newPw);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkIsBeforePW
 * @author Inswave
 * @date 2026. 09. 29
 * @param gbCd pw
 * @returns
 * @hidden N
*/
scwin.checkIsBeforePW = async function (gbCd, pw) {
    /* sdd-asis-lifecycle:begin checkIsBeforePW — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (pw.length > 0) {
        scwin.checkIdAjax(gbCd, pw);
    } else {
        if (gbCd === "A") {
            await alertE("현재 비밀번호를 입력하시기 바랍니다");
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.checkIdAjax = scwin.tx_checkIdAjax;

/**
 * @method
 * @name scwin.checkSafety_done
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.checkSafety_done = async function (data) {
    /* sdd-asis-lifecycle:begin checkSafety_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_isPass').setValue(scwin.result.isPass);
    $c.util.getComponent('ipt_selfLevel').setValue(scwin.result.selfLevel);
    $c.util.getComponent('txt_msgLevel').setLabel(scwin.result.msgLevel);
    if (scwin.result.msgInfomation !== "") {
        await alertE(scwin.result.msgInfomation.replace(/<br\/>/gi, "\n"));
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.checkSafety
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkSafety = async function () {
    const r = await scwin.tx_checkSafety();
    try {
        scwin.checkSafety_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldods10010.checkSafety' });
    }
    return r;
};
